// The only place to configure this workflow.
const SUPABASE_URL = '';                 // TODO: https://<project>.supabase.co
const CHAT_ID = '';                      // TODO: chat that receives the weekly report
const MODEL = 'claude-sonnet-4-5';       // the model whose answers are being measured
const MAX_TOKENS = 700;

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');
if (!CHAT_ID) throw new Error('CHAT_ID is not configured in "Config"');

const base = SUPABASE_URL.replace(/\/+$/, '');
const runDate = new Date().toISOString().slice(0, 10);

return [{
  json: {
    chatId: CHAT_ID,
    model: MODEL,
    maxTokens: MAX_TOKENS,
    runDate,
    brandsUrl: base + '/rest/v1/brands?enabled=eq.true',
    promptsUrl: base + '/rest/v1/prompts?enabled=eq.true',
    runsUrl: base + '/rest/v1/visibility_runs',
    // Everything measured before today, newest first: the previous run is whatever the
    // latest earlier run_date happens to be, so a skipped week still compares correctly.
    historyUrl: base + '/rest/v1/visibility_runs?run_date=lt.' + runDate
      + '&select=run_date,brand_id,prompt_id,mentioned,position,cited,model'
      + '&order=run_date.desc&limit=2000',
  },
}];

// One request per prompt. The prompt is asked as a user would ask it: no schema, no
// JSON instruction, nothing that would change the answer being measured.
const cfg = $('Config').first().json;
const brands = $('Load brands').all().map((i) => i.json);
const prompts = $input.all().map((i) => i.json);

const byId = new Map(brands.map((b) => [b.id, b]));

const requests = [];
for (const p of prompts) {
  const brand = byId.get(p.brand_id);
  if (!brand) continue;
  requests.push({
    promptId: p.id,
    brandId: brand.id,
    intent: p.intent || 'informational',
    promptText: p.text,
    brand: { name: brand.name, domain: brand.domain || null, aliases: Array.isArray(brand.aliases) ? brand.aliases : [] },
    competitors: Array.isArray(brand.competitors) ? brand.competitors : [],
    model: cfg.model,
    runDate: cfg.runDate,
    url: 'https://api.anthropic.com/v1/messages',
    body: {
      model: cfg.model,
      max_tokens: cfg.maxTokens,
      messages: [{ role: 'user', content: p.text }],
    },
  });
}

if (!requests.length) throw new Error('no enabled prompts matched an enabled brand');
return requests.map((json) => ({ json }));

// Turns answers into measurements. Detection is deliberately boring and checkable:
// word-boundary matching on names and aliases, plain substring for domains.
const cfg = $('Config').first().json;
const requests = $('Build measurement requests').all().map((i) => i.json);
const answers = $input.all();

// A brand called "Lune" must not match "Lunela". Word boundaries in JS do not treat a
// dot or a hyphen as part of a word, so names are escaped and wrapped explicitly.
const escapeRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const firstIndexOfName = (text, name) => {
  const re = new RegExp('(^|[^\\p{L}\\p{N}])' + escapeRe(name) + '($|[^\\p{L}\\p{N}])', 'iu');
  const m = re.exec(text);
  return m ? m.index : -1;
};
const firstIndexOfDomain = (text, domain) => {
  if (!domain) return -1;
  const i = text.toLowerCase().indexOf(String(domain).toLowerCase());
  return i;
};

const rows = [];
let failed = 0;

for (let idx = 0; idx < answers.length; idx++) {
  const req = requests[idx];
  if (!req) continue;
  const res = answers[idx].json || {};

  const text = Array.isArray(res.content)
    ? res.content.filter((c) => c.type === 'text').map((c) => c.text).join('')
    : '';

  if (!text) {
    // A failed call is not a zero. Recording it as "not mentioned" would invent a drop.
    failed++;
    continue;
  }

  const names = [req.brand.name, ...req.brand.aliases].filter(Boolean);
  let brandIdx = -1;
  for (const n of names) {
    const i = firstIndexOfName(text, n);
    if (i !== -1 && (brandIdx === -1 || i < brandIdx)) brandIdx = i;
  }
  const domainIdx = firstIndexOfDomain(text, req.brand.domain);
  const cited = domainIdx !== -1;
  if (brandIdx === -1 && cited) brandIdx = domainIdx;

  // Position is a rank among tracked names, not a character offset: "third thing
  // mentioned" is what a human reads, and it survives answers of different lengths.
  const marks = [];
  if (brandIdx !== -1) marks.push({ who: 'brand', at: brandIdx });
  for (const c of req.competitors) {
    const cNames = [c.name, ...(Array.isArray(c.aliases) ? c.aliases : [])].filter(Boolean);
    let ci = -1;
    for (const n of cNames) {
      const i = firstIndexOfName(text, n);
      if (i !== -1 && (ci === -1 || i < ci)) ci = i;
    }
    const cd = firstIndexOfDomain(text, c.domain);
    if (ci === -1 && cd !== -1) ci = cd;
    if (ci !== -1) marks.push({ who: c.name, at: ci });
  }
  marks.sort((a, b) => a.at - b.at);
  const position = brandIdx === -1 ? null : marks.findIndex((m) => m.who === 'brand') + 1;

  rows.push({
    run_date: req.runDate,
    brand_id: req.brandId,
    prompt_id: req.promptId,
    model: req.model,
    mentioned: brandIdx !== -1,
    position,
    cited,
    answer: text.slice(0, 2000),
  });
}

return [{
  json: {
    rows,
    measured: rows.length,
    failed,
    runDate: cfg.runDate,
    model: cfg.model,
    chatId: cfg.chatId,
    runsUrl: cfg.runsUrl,
  },
}];

// Compares this run with the previous one and writes the message. A delta needs a
// baseline, and the baseline is whatever the most recent earlier run_date holds, so a
// skipped week compares against the last real measurement rather than against nothing.
const state = $('Detect mentions').first().json;
const history = $input.all().map((i) => i.json).filter((r) => r && r.run_date);

const rows = state.rows;
const share = (list) => (list.length ? list.filter((r) => r.mentioned).length / list.length : 0);

const relevant = history.filter((h) => h.model === state.model);
const previousDate = relevant.length ? relevant[0].run_date : null;
const previous = relevant.filter((h) => h.run_date === previousDate);
const prevByPrompt = new Map(previous.map((p) => [p.prompt_id, p]));

const nowShare = share(rows);
const prevShare = previous.length ? share(previous) : null;
const delta = prevShare === null ? null : nowShare - prevShare;

const lost = rows.filter((r) => !r.mentioned && prevByPrompt.get(r.prompt_id)?.mentioned);
const gained = rows.filter((r) => r.mentioned && prevByPrompt.get(r.prompt_id) && !prevByPrompt.get(r.prompt_id).mentioned);

const pct = (x) => (x * 100).toFixed(0) + '%';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const parts = ['<b>AI search visibility</b>', ''];
parts.push('Mentioned in ' + rows.filter((r) => r.mentioned).length + ' of ' + rows.length
  + ' answers (' + pct(nowShare) + ')');
if (delta === null) {
  parts.push('No earlier run to compare against yet.');
} else {
  const sign = delta > 0 ? '+' : '';
  parts.push('Previous run ' + previousDate + ': ' + pct(prevShare)
    + ' · change ' + sign + (delta * 100).toFixed(0) + ' points');
}
const cited = rows.filter((r) => r.cited).length;
parts.push('Domain cited in ' + cited + ' answer' + (cited === 1 ? '' : 's'));
if (state.failed) parts.push(state.failed + ' prompt' + (state.failed === 1 ? '' : 's') + ' failed and were not recorded');
parts.push('');

if (lost.length) {
  parts.push('<b>Lost since last run</b>');
  for (const r of lost.slice(0, 10)) parts.push('• ' + esc(r.prompt_id));
  parts.push('');
}
if (gained.length) {
  parts.push('<b>Gained</b>');
  for (const r of gained.slice(0, 10)) parts.push('• ' + esc(r.prompt_id));
  parts.push('');
}
parts.push('<i>Model ' + esc(state.model) + ', run ' + esc(state.runDate) + '. Measurement only, no causes.</i>');

return [{
  json: {
    rows,
    stored: rows.length,
    nowShare,
    prevShare,
    previousDate,
    delta,
    lost: lost.length,
    gained: gained.length,
    failed: state.failed,
    chatId: state.chatId,
    runsUrl: state.runsUrl,
    text: parts.join('\n').trim(),
  },
}];
